{"implementation": "def solve(case):
    threshold = case["threshold"]
    calls = case["calls"]

    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    required_call_fields = ["call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"]

    diagnostics = []
    accepted_call_ids = []

    for call in calls:
        for field in required_call_fields:
            if field not in call:
                raise ValueError(f"Missing required field '{field}' in call")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(tokens, (int, float)) or tokens < 1:
            raise ValueError(f"prediction_tokens must be >= 1 for call {call_id}")
        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"loss_without_call must be numeric for call {call_id}")
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"loss_with_call must be numeric for call {call_id}")

        normalized_gain = (loss_without - loss_with) / tokens
        normalized_gain_rounded = round(normalized_gain, 6)

        accepted = bool(parseable) and (normalized_gain >= threshold)

        diagnostics.append({
            "call_id": call_id,
            "normalized_gain": normalized_gain_rounded,
            "accepted": accepted
        })

        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }
